From b6c5dd308dbffd9920196f11699bac355bd93959 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:55:19 +0100
Subject: [PATCH] window: honor the resizable edges of plasma surfaces

Meta+right-drag and the resize shortcut picked the edges to move only
from the pointer position, so an applet popup could be pulled over its
panel. They now skip the edges the surface doesn't allow to be resized.

BUG: 507821
---
 src/wayland/plasmashell.cpp | 19 ++++++++++++++++++-
 src/wayland/plasmashell.h   |  6 ++++++
 src/window.cpp              | 31 ++++++++++++++++++++++++-------
 src/window.h                |  5 +++++
 src/xdgshellwindow.cpp      |  8 ++++++++
 src/xdgshellwindow.h        |  1 +
 6 files changed, 62 insertions(+), 8 deletions(-)

diff --git a/src/wayland/plasmashell.cpp b/src/wayland/plasmashell.cpp
index 51d34a5755..021d4dcf93 100644
--- a/src/wayland/plasmashell.cpp
+++ b/src/wayland/plasmashell.cpp
@@ -16,7 +16,7 @@
 namespace KWin
 {

-static const quint32 s_version = 8;
+static const quint32 s_version = 9;
 static QList<PlasmaShellSurfaceInterface *> s_shellSurfaces;

 class PlasmaShellSurfaceCommit : public SurfaceAttachedState<PlasmaShellSurfaceCommit>
@@ -57,6 +57,7 @@ public:
     bool m_skipSwitcher = false;
     bool m_panelTakesFocus = false;
     bool m_openUnderCursorRequested = false;
+    Qt::Edges m_resizableEdges = Qt::TopEdge | Qt::BottomEdge | Qt::LeftEdge | Qt::RightEdge;

 private:
     void org_kde_plasma_surface_destroy_resource(Resource *resource) override;
@@ -71,6 +72,7 @@ private:
     void org_kde_plasma_surface_set_panel_takes_focus(Resource *resource, uint32_t takes_focus) override;
     void org_kde_plasma_surface_set_skip_switcher(Resource *resource, uint32_t skip) override;
     void org_kde_plasma_surface_open_under_cursor(Resource *resource) override;
+    void org_kde_plasma_surface_set_resizable_edges(Resource *resource, uint32_t edges) override;
 };

 PlasmaShellInterface::PlasmaShellInterface(Display *display, QObject *parent)
@@ -293,6 +295,16 @@ bool PlasmaShellSurfaceInterface::isPositionSet() const
     return d->m_globalPos.has_value();
 }

+void PlasmaShellSurfaceInterfacePrivate::org_kde_plasma_surface_set_resizable_edges(Resource *resource, uint32_t edges)
+{
+    Qt::Edges resizableEdges;
+    resizableEdges.setFlag(Qt::TopEdge, edges & edge_top);
+    resizableEdges.setFlag(Qt::BottomEdge, edges & edge_bottom);
+    resizableEdges.setFlag(Qt::LeftEdge, edges & edge_left);
+    resizableEdges.setFlag(Qt::RightEdge, edges & edge_right);
+    m_resizableEdges = resizableEdges;
+}
+
 bool PlasmaShellSurfaceInterface::wantsOpenUnderCursor() const
 {
     return d->m_openUnderCursorRequested;
@@ -328,6 +340,11 @@ bool PlasmaShellSurfaceInterface::panelTakesFocus() const
     return d->m_panelTakesFocus;
 }

+Qt::Edges PlasmaShellSurfaceInterface::resizableEdges() const
+{
+    return d->m_resizableEdges;
+}
+
 PlasmaShellSurfaceInterface *PlasmaShellSurfaceInterface::get(wl_resource *native)
 {
     if (auto surfacePrivate = resource_cast<PlasmaShellSurfaceInterfacePrivate *>(native)) {
diff --git a/src/wayland/plasmashell.h b/src/wayland/plasmashell.h
index d62d3272b8..ae73853991 100644
--- a/src/wayland/plasmashell.h
+++ b/src/wayland/plasmashell.h
@@ -161,6 +161,12 @@ public:
     // TODO KF6 rename to something generic
     bool panelTakesFocus() const;

+    /**
+     * @returns The edges the compositor may move when the user resizes the surface with a
+     * compositor action, such as a modifier drag or a keyboard shortcut. All edges by default.
+     */
+    Qt::Edges resizableEdges() const;
+
     /**
      * @returns The PlasmaShellSurfaceInterface for the @p native resource.
      */
diff --git a/src/window.cpp b/src/window.cpp
index 214e2d7671..dc747263a7 100644
--- a/src/window.cpp
+++ b/src/window.cpp
@@ -2188,26 +2188,38 @@ bool Window::performMousePressCommand(Options::MouseCommand cmd, const QPointF &
         if (!isResizable()) {
             break;
         }
+        const QPointF moveOffset = QPointF(globalPos.x() - x(), globalPos.y() - y()); // map from global
+        int x = moveOffset.x(), y = moveOffset.y();
+        bool left = x < width() / 3;
+        bool right = x >= 2 * width() / 3;
+        bool top = y < height() / 3;
+        bool bot = y >= 2 * height() / 3;
+        if (!top && !bot) {
+            left = x < width() / 2;
+            right = !left;
+        }
+        const Qt::Edges edges = resizableEdges();
+        left = left && edges.testFlag(Qt::LeftEdge);
+        right = right && edges.testFlag(Qt::RightEdge);
+        top = top && edges.testFlag(Qt::TopEdge);
+        bot = bot && edges.testFlag(Qt::BottomEdge);
+        if (!left && !right && !top && !bot) {
+            break;
+        }
         if (isInteractiveMoveResize()) {
             finishInteractiveMoveResize(false);
         }
         setInteractiveMoveResizePointerButtonDown(true);
         setInteractiveMoveResizeAnchor(globalPos);
         setInteractiveMoveResizeModifiers(Qt::KeyboardModifiers());
-        const QPointF moveOffset = QPointF(globalPos.x() - x(), globalPos.y() - y()); // map from global
         setInteractiveMoveOffset(QPointF(moveOffset.x() / width(), moveOffset.y() / height()));
-        int x = moveOffset.x(), y = moveOffset.y();
-        bool left = x < width() / 3;
-        bool right = x >= 2 * width() / 3;
-        bool top = y < height() / 3;
-        bool bot = y >= 2 * height() / 3;
         Gravity gravity;
         if (top) {
             gravity = left ? Gravity::TopLeft : (right ? Gravity::TopRight : Gravity::Top);
         } else if (bot) {
             gravity = left ? Gravity::BottomLeft : (right ? Gravity::BottomRight : Gravity::Bottom);
         } else {
-            gravity = (x < width() / 2) ? Gravity::Left : Gravity::Right;
+            gravity = left ? Gravity::Left : Gravity::Right;
         }
         setInteractiveMoveResizeGravity(gravity);
         setUnrestrictedInteractiveMoveResize((cmd == Options::MouseUnrestrictedResize));
@@ -2223,6 +2235,11 @@ bool Window::performMousePressCommand(Options::MouseCommand cmd, const QPointF &
     return consumes;
 }

+Qt::Edges Window::resizableEdges() const
+{
+    return Qt::TopEdge | Qt::BottomEdge | Qt::LeftEdge | Qt::RightEdge;
+}
+
 void Window::performMouseReleaseCommand(Options::MouseCommand command, const QPointF &globalPos)
 {
     if (command != Options::MouseActivateRaiseOnReleaseAndPassClick) {
