From 7acb3c5948351b025253e2f142d2eae8479602b0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:55:20 +0100
Subject: [PATCH] AppletPopup: tell the compositor which edges can be resized

Meta+right-drag in KWin could resize an applet popup from the edges
facing its panel or the screen edge, which its own resize handles leave
out. The popup now sends the same edges to the compositor on Wayland.

BUG: 507821
---
 src/plasmaquick/appletpopup.cpp               |  1 +
 .../plasmashellwaylandintegration.cpp         | 38 ++++++++++++++++++-
 .../plasmashellwaylandintegration.h           |  9 +++++
 3 files changed, 47 insertions(+), 1 deletion(-)

diff --git a/src/plasmaquick/appletpopup.cpp b/src/plasmaquick/appletpopup.cpp
index edb9c6885..593b9e231 100644
--- a/src/plasmaquick/appletpopup.cpp
+++ b/src/plasmaquick/appletpopup.cpp
@@ -80,6 +80,7 @@ AppletPopup::AppletPopup()

     auto updateWindowResizerEdges = [windowResizer, this]() {
         windowResizer->setActiveEdges(~nearbyBorders());
+        PlasmaShellWaylandIntegration::get(this)->setResizableEdges(~nearbyBorders());
     };
     updateWindowResizerEdges();
     connect(this, &PopupPlasmaWindow::nearbyBordersChanged, this, updateWindowResizerEdges);
diff --git a/src/plasmaquick/plasmashellwaylandintegration.cpp b/src/plasmaquick/plasmashellwaylandintegration.cpp
index c3af1b75c..3816fe1b9 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.cpp
+++ b/src/plasmaquick/plasmashellwaylandintegration.cpp
@@ -19,7 +19,7 @@ class PlasmaShellManager : public QWaylandClientExtensionTemplate<PlasmaShellMan
 {
 public:
     PlasmaShellManager()
-        : QWaylandClientExtensionTemplate<PlasmaShellManager>(8)
+        : QWaylandClientExtensionTemplate<PlasmaShellManager>(9)
     {
         initialize();
     }
@@ -63,6 +63,7 @@ public:
     void platformSurfaceCreated(QWindow *window);
     void surfaceCreated();
     void surfaceDestroyed();
+    void sendResizableEdges();

     PlasmaShellWaylandIntegration *q;
     QWindow *m_window = nullptr;
@@ -71,6 +72,7 @@ public:
     QtWayland::org_kde_plasma_surface::role m_role = QtWayland::org_kde_plasma_surface::role_normal;
     bool m_takesFocus = false;
     bool m_openUnderCursor = false;
+    Qt::Edges m_resizableEdges = Qt::TopEdge | Qt::BottomEdge | Qt::LeftEdge | Qt::RightEdge;
     std::unique_ptr<PlasmaShellSurface> m_shellSurface;
 };

@@ -121,9 +123,31 @@ void PlasmaShellWaylandIntegrationPrivate::surfaceCreated()
         if (m_openUnderCursor) {
             m_shellSurface->open_under_cursor();
         }
+        sendResizableEdges();
     }
 }

+void PlasmaShellWaylandIntegrationPrivate::sendResizableEdges()
+{
+    if (m_shellSurface->version() < ORG_KDE_PLASMA_SURFACE_SET_RESIZABLE_EDGES_SINCE_VERSION) {
+        return;
+    }
+    uint32_t edges = 0;
+    if (m_resizableEdges & Qt::TopEdge) {
+        edges |= QtWayland::org_kde_plasma_surface::edge_top;
+    }
+    if (m_resizableEdges & Qt::BottomEdge) {
+        edges |= QtWayland::org_kde_plasma_surface::edge_bottom;
+    }
+    if (m_resizableEdges & Qt::LeftEdge) {
+        edges |= QtWayland::org_kde_plasma_surface::edge_left;
+    }
+    if (m_resizableEdges & Qt::RightEdge) {
+        edges |= QtWayland::org_kde_plasma_surface::edge_right;
+    }
+    m_shellSurface->set_resizable_edges(edges);
+}
+
 void PlasmaShellWaylandIntegrationPrivate::surfaceDestroyed()
 {
     m_shellSurface.reset();
@@ -228,4 +252,16 @@ void PlasmaShellWaylandIntegration::openUnderCursor()
     }
 }

+void PlasmaShellWaylandIntegration::setResizableEdges(Qt::Edges edges)
+{
+    if (edges == d->m_resizableEdges) {
+        return;
+    }
+    d->m_resizableEdges = edges;
+
+    if (d->m_shellSurface) {
+        d->sendResizableEdges();
+    }
+}
+
 #include "moc_plasmashellwaylandintegration.cpp"
diff --git a/src/plasmaquick/plasmashellwaylandintegration.h b/src/plasmaquick/plasmashellwaylandintegration.h
index 99e334e86..c1019b0b2 100644
--- a/src/plasmaquick/plasmashellwaylandintegration.h
+++ b/src/plasmaquick/plasmashellwaylandintegration.h
@@ -68,6 +68,15 @@ public:
      */
     void openUnderCursor();

+    /*!
+     * Sets the edges the compositor may move when the user resizes the window
+     * with a compositor action, such as dragging it with a modifier key held.
+     * All edges by default.
+     *
+     * \since 6.9
+     */
+    void setResizableEdges(Qt::Edges edges);
+
     bool eventFilter(QObject *watched, QEvent *event) override;

 private:
-- 
